ALTER TABLE "site_settings"
  ADD COLUMN "faqs" JSONB NOT NULL DEFAULT '[{"question":"¿Cómo puedo realizar una donación?","answer":"Puedes realizar transferencias directas a nuestra cuenta bancaria en Banco Industrial. Para donaciones desde el extranjero o uso de tarjeta, contáctanos a nuestro WhatsApp para enviarte un enlace de pago seguro."},{"question":"¿Dónde puedo entregar mis donaciones en especie?","answer":"Recibimos donaciones físicas en nuestro centro de acopio principal ubicado en Zona 10, Ciudad de Guatemala, Lunes a sábado de 9:00 AM a 4:00 PM. Por favor, comunícate con nosotros para coordinar tu visita."},{"question":"¿Cómo se utilizan las donaciones?","answer":"El 100% de las donaciones se destina directamente al bienestar animal. Los fondos cubren facturas veterinarias, cirugías de emergencia, medicamentos, alimentos, y gastos de refugios temporales. Publicamos reportes de transparencia trimestrales en nuestra plataforma."}]'::jsonb;
